-- 055_normalize_g6_static_readability.sql
--
-- Guarded Grade 6 static source normalization.
-- Generated deterministically from the live read-only 33-item export.
--
-- SQL Editor compatibility: all reviewed rows are carried inside one server-side
-- DO block. No temporary table is used, so no SQL Editor statement boundary can
-- discard the reviewed source set before its precondition checks run.
--
-- Allowed changes, and only to the exact IDs below:
--   1) trim edge whitespace from question_text and option text;
--   2) collapse repeated whitespace in explanation;
--   3) append a terminal question mark only when a trimmed prompt has no clear terminal punctuation.
--
-- No change is permitted to: concept mapping, question type, correct answer,
-- answer index, difficulty, images, solution steps, active/verified state, or
-- any item outside this exact 33-item set.
--
-- Do NOT run until the matching source manifest and read-only preflight have
-- been inspected. The block fails before update if live source text drifts.

DO $g6_static_normalization$
DECLARE
  expected_count integer := 33;
  source_rows jsonb := $g6_static_source$[{"id":"2acb712d-db45-457c-9089-a7869a416460","lesson_number":"M6.EE.1.3","question_type":"multiple_choice","before_question_text":"In the expression 5x^2 + 3x - 7, what is the coefficient of x ","before_options":[{"key":"A","text":"5"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"-7"}],"correct_answer":"C","before_explanation":"The coefficient is the number multiplied by the variable. In 3x, the coefficient is 3.","after_question_text":"In the expression 5x^2 + 3x - 7, what is the coefficient of x?","after_options":[{"key":"A","text":"5"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"-7"}],"after_explanation":"The coefficient is the number multiplied by the variable. In 3x, the coefficient is 3."},{"id":"68c88803-4aa2-46a6-b979-ec3ec2fd8579","lesson_number":"M6.EE.1.3","question_type":"multiple_choice","before_question_text":"In the expression 4y^3, what is the exponent ","before_options":[{"key":"A","text":"4"},{"key":"B","text":"y"},{"key":"C","text":"3"},{"key":"D","text":"4y"}],"correct_answer":"C","before_explanation":"The exponent tells how many times the base is multiplied by itself. In y^3, the exponent is 3.","after_question_text":"In the expression 4y^3, what is the exponent?","after_options":[{"key":"A","text":"4"},{"key":"B","text":"y"},{"key":"C","text":"3"},{"key":"D","text":"4y"}],"after_explanation":"The exponent tells how many times the base is multiplied by itself. In y^3, the exponent is 3."},{"id":"d7da2c15-29df-4f94-9fe9-adac8f4b0ad8","lesson_number":"M6.EE.1.3","question_type":"multiple_choice","before_question_text":"Which of the following are like terms ","before_options":[{"key":"A","text":"3x and 3y"},{"key":"B","text":"5x^2 and 5x"},{"key":"C","text":"4ab and 7ab"},{"key":"D","text":"2x and 2x^2"}],"correct_answer":"C","before_explanation":"Like terms have identical variable parts. 4ab and 7ab both have the variable ab.","after_question_text":"Which of the following are like terms?","after_options":[{"key":"A","text":"3x and 3y"},{"key":"B","text":"5x^2 and 5x"},{"key":"C","text":"4ab and 7ab"},{"key":"D","text":"2x and 2x^2"}],"after_explanation":"Like terms have identical variable parts. 4ab and 7ab both have the variable ab."},{"id":"3f8c370e-4f71-4d1b-bdf4-2200ea59a3db","lesson_number":"M6.EE.3.1","question_type":"multiple_choice","before_question_text":"Which value of n is a solution to the inequality n + 3 > 10 ","before_options":[{"key":"A","text":"n = 5"},{"key":"B","text":"n = 7"},{"key":"C","text":"n = 8"},{"key":"D","text":"n = 6"}],"correct_answer":"C","before_explanation":"8 + 3 = 11 > 10  . Check: 5+3=8, 7+3=10 (not strictly greater), 6+3=9.","after_question_text":"Which value of n is a solution to the inequality n + 3 > 10?","after_options":[{"key":"A","text":"n = 5"},{"key":"B","text":"n = 7"},{"key":"C","text":"n = 8"},{"key":"D","text":"n = 6"}],"after_explanation":"8 + 3 = 11 > 10 . Check: 5+3=8, 7+3=10 (not strictly greater), 6+3=9."},{"id":"966d9d5f-125c-4d97-bf04-a4fa043b76b7","lesson_number":"M6.EE.3.1","question_type":"multiple_choice","before_question_text":"Which value of x makes the equation 2x + 5 = 17 true ","before_options":[{"key":"A","text":"x = 4"},{"key":"B","text":"x = 6"},{"key":"C","text":"x = 11"},{"key":"D","text":"x = 7"}],"correct_answer":"B","before_explanation":"2(6) + 5 = 12 + 5 = 17  . Use substitution to verify.","after_question_text":"Which value of x makes the equation 2x + 5 = 17 true?","after_options":[{"key":"A","text":"x = 4"},{"key":"B","text":"x = 6"},{"key":"C","text":"x = 11"},{"key":"D","text":"x = 7"}],"after_explanation":"2(6) + 5 = 12 + 5 = 17 . Use substitution to verify."},{"id":"3146a26b-c379-4120-b918-40684f040d9f","lesson_number":"M6.EE.4.1","question_type":"multiple_choice","before_question_text":"An elevator can hold at most 2,000 pounds. If w = total weight, which inequality represents the safe load ","before_options":[{"key":"A","text":"w > 2000"},{"key":"B","text":"w >= 2000"},{"key":"C","text":"w < 2000"},{"key":"D","text":"w <= 2000"}],"correct_answer":"D","before_explanation":"'At most 2,000' means 2,000 or less, so w <= 2000.","after_question_text":"An elevator can hold at most 2,000 pounds. If w = total weight, which inequality represents the safe load?","after_options":[{"key":"A","text":"w > 2000"},{"key":"B","text":"w >= 2000"},{"key":"C","text":"w < 2000"},{"key":"D","text":"w <= 2000"}],"after_explanation":"'At most 2,000' means 2,000 or less, so w <= 2000."},{"id":"c5ed474f-bc4f-4148-9592-edad53276dcc","lesson_number":"M6.EE.4.1","question_type":"multiple_choice","before_question_text":"A roller coaster has a minimum height requirement. Which inequality best represents 'riders must be at least 48 inches tall' where h = height ","before_options":[{"key":"A","text":"h < 48"},{"key":"B","text":"h > 48"},{"key":"C","text":"h >= 48"},{"key":"D","text":"h <= 48"}],"correct_answer":"C","before_explanation":"'At least 48' means 48 or more, so h >= 48.","after_question_text":"A roller coaster has a minimum height requirement. Which inequality best represents 'riders must be at least 48 inches tall' where h = height?","after_options":[{"key":"A","text":"h < 48"},{"key":"B","text":"h > 48"},{"key":"C","text":"h >= 48"},{"key":"D","text":"h <= 48"}],"after_explanation":"'At least 48' means 48 or more, so h >= 48."},{"id":"5cbcccce-1ffb-4577-a6d3-1a62c8a91fbd","lesson_number":"M6.EE.5.1","question_type":"multiple_choice","before_question_text":"In the relationship 'total earnings depends on hours worked', which is the independent variable ","before_options":[{"key":"A","text":"Total earnings"},{"key":"B","text":"Hours worked"},{"key":"C","text":"Hourly pay rate"},{"key":"D","text":"Number of days"}],"correct_answer":"B","before_explanation":"The independent variable is the input -- what you control. Hours worked determines earnings, so it is independent.","after_question_text":"In the relationship 'total earnings depends on hours worked', which is the independent variable?","after_options":[{"key":"A","text":"Total earnings"},{"key":"B","text":"Hours worked"},{"key":"C","text":"Hourly pay rate"},{"key":"D","text":"Number of days"}],"after_explanation":"The independent variable is the input -- what you control. Hours worked determines earnings, so it is independent."},{"id":"f62048af-75b9-4579-b7f5-3891d0bea086","lesson_number":"M6.EE.5.1","question_type":"multiple_choice","before_question_text":"A plant's height (y) grows 2 cm per week (x). Which variable is dependent ","before_options":[{"key":"A","text":"Weeks (x)"},{"key":"B","text":"Height (y)"},{"key":"C","text":"Both are dependent"},{"key":"D","text":"Neither"}],"correct_answer":"B","before_explanation":"Height depends on the number of weeks, so height (y) is the dependent variable.","after_question_text":"A plant's height (y) grows 2 cm per week (x). Which variable is dependent?","after_options":[{"key":"A","text":"Weeks (x)"},{"key":"B","text":"Height (y)"},{"key":"C","text":"Both are dependent"},{"key":"D","text":"Neither"}],"after_explanation":"Height depends on the number of weeks, so height (y) is the dependent variable."},{"id":"84d14d9f-b4a0-473c-81be-5df5beb469f7","lesson_number":"M6.GEO.2.1","question_type":"multiple_choice","before_question_text":"Which net correctly folds into a cube ","before_options":[{"key":"A","text":"A cross shape made of 6 squares"},{"key":"B","text":"A row of 4 squares with 2 attached at one end"},{"key":"C","text":"A T-shape made of 6 squares"},{"key":"D","text":"All of the above"}],"correct_answer":"D","before_explanation":"There are 11 valid nets for a cube. Crosses, T-shapes, and L-shapes can all fold into cubes.","after_question_text":"Which net correctly folds into a cube?","after_options":[{"key":"A","text":"A cross shape made of 6 squares"},{"key":"B","text":"A row of 4 squares with 2 attached at one end"},{"key":"C","text":"A T-shape made of 6 squares"},{"key":"D","text":"All of the above"}],"after_explanation":"There are 11 valid nets for a cube. Crosses, T-shapes, and L-shapes can all fold into cubes."},{"id":"d89b310b-a522-4e3d-b4d0-4b4596178953","lesson_number":"M6.GEO.2.1","question_type":"multiple_choice","before_question_text":"A rectangular prism has 6 faces. How many pairs of congruent (identical) faces does it have ","before_options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"6"},{"key":"D","text":"1"}],"correct_answer":"B","before_explanation":"A rectangular prism has 3 pairs of congruent faces: top/bottom, front/back, left/right.","after_question_text":"A rectangular prism has 6 faces. How many pairs of congruent (identical) faces does it have?","after_options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"6"},{"key":"D","text":"1"}],"after_explanation":"A rectangular prism has 3 pairs of congruent faces: top/bottom, front/back, left/right."},{"id":"f238dda9-5470-4d12-8f15-e4ee78c72c6a","lesson_number":"M6.GEO.3.1","question_type":"multiple_choice","before_question_text":"A rectangular prism is filled with unit cubes. Each layer has 4 x 3 = 12 cubes and there are 5 layers. What is the volume ","before_options":[{"key":"A","text":"12 cubic units"},{"key":"B","text":"17 cubic units"},{"key":"C","text":"60 cubic units"},{"key":"D","text":"7 cubic units"}],"correct_answer":"C","before_explanation":"Volume = base area x height = 12 x 5 = 60 cubic units. This demonstrates V = Bh.","after_question_text":"A rectangular prism is filled with unit cubes. Each layer has 4 x 3 = 12 cubes and there are 5 layers. What is the volume?","after_options":[{"key":"A","text":"12 cubic units"},{"key":"B","text":"17 cubic units"},{"key":"C","text":"60 cubic units"},{"key":"D","text":"7 cubic units"}],"after_explanation":"Volume = base area x height = 12 x 5 = 60 cubic units. This demonstrates V = Bh."},{"id":"f0c26925-0703-4ed7-abb7-3dd1dbd5b95d","lesson_number":"M6.GEO.4.2","question_type":"multiple_choice","before_question_text":"Mia wants to wrap a gift box that is 10 cm x 8 cm x 5 cm. Approximately how many square centimeters of wrapping paper does she need (surface area) ","before_options":[{"key":"A","text":"400 cm^2"},{"key":"B","text":"340 cm^2"},{"key":"C","text":"300 cm^2"},{"key":"D","text":"160 cm^2"}],"correct_answer":"B","before_explanation":"SA = 2(10x8) + 2(10x5) + 2(8x5) = 160 + 100 + 80 = 340 cm^2.","after_question_text":"Mia wants to wrap a gift box that is 10 cm x 8 cm x 5 cm. Approximately how many square centimeters of wrapping paper does she need (surface area)?","after_options":[{"key":"A","text":"400 cm^2"},{"key":"B","text":"340 cm^2"},{"key":"C","text":"300 cm^2"},{"key":"D","text":"160 cm^2"}],"after_explanation":"SA = 2(10x8) + 2(10x5) + 2(8x5) = 160 + 100 + 80 = 340 cm^2."},{"id":"398bf61a-25a7-433d-bd1e-81844a291cf4","lesson_number":"M6.NS.2.1","question_type":"multiple_choice","before_question_text":"Which expression represents the question: 'How many 1/3-cup servings are in 2 cups '","before_options":[{"key":"A","text":"2 x 1/3"},{"key":"B","text":"2 / 1/3"},{"key":"C","text":"1/3 / 2"},{"key":"D","text":"2 - 1/3"}],"correct_answer":"B","before_explanation":"Dividing the total by the serving size gives the number of servings: 2 / 1/3 = 6.","after_question_text":"Which expression represents the question: 'How many 1/3-cup servings are in 2 cups '?","after_options":[{"key":"A","text":"2 x 1/3"},{"key":"B","text":"2 / 1/3"},{"key":"C","text":"1/3 / 2"},{"key":"D","text":"2 - 1/3"}],"after_explanation":"Dividing the total by the serving size gives the number of servings: 2 / 1/3 = 6."},{"id":"cc4dc9f7-4dca-4431-a135-4bb783c689b1","lesson_number":"M6.NS.2.1","question_type":"multiple_choice","before_question_text":"A recipe calls for 1/2 cup of oil. Marcos only has a 1/8 cup measuring cup. Which expression gives the number of times he must fill it ","before_options":[{"key":"A","text":"1/2 x 1/8"},{"key":"B","text":"1/8 / 1/2"},{"key":"C","text":"1/2 / 1/8"},{"key":"D","text":"1/2 + 1/8"}],"correct_answer":"C","before_explanation":"1/2 / 1/8 = 1/2 x 8 = 4. He fills the 1/8-cup measure 4 times.","after_question_text":"A recipe calls for 1/2 cup of oil. Marcos only has a 1/8 cup measuring cup. Which expression gives the number of times he must fill it?","after_options":[{"key":"A","text":"1/2 x 1/8"},{"key":"B","text":"1/8 / 1/2"},{"key":"C","text":"1/2 / 1/8"},{"key":"D","text":"1/2 + 1/8"}],"after_explanation":"1/2 / 1/8 = 1/2 x 8 = 4. He fills the 1/8-cup measure 4 times."},{"id":"d59e9723-3806-4bbb-b432-379c9ae5ae30","lesson_number":"M6.NS.2.1","question_type":"multiple_choice","before_question_text":"On a number line, which model shows 3/4 / 1/4 ","before_options":[{"key":"A","text":"Starting at 0, jumping 1/4 three times"},{"key":"B","text":"Starting at 3/4, going back 1/4 once"},{"key":"C","text":"Starting at 0 and jumping 3/4 four times"},{"key":"D","text":"Dividing the segment from 0 to 3/4 into equal parts of 1/4 and counting them"}],"correct_answer":"D","before_explanation":"Fraction division 3/4 / 1/4 asks: how many 1/4-size pieces fit in 3/4  Answer: 3.","after_question_text":"On a number line, which model shows 3/4 / 1/4?","after_options":[{"key":"A","text":"Starting at 0, jumping 1/4 three times"},{"key":"B","text":"Starting at 3/4, going back 1/4 once"},{"key":"C","text":"Starting at 0 and jumping 3/4 four times"},{"key":"D","text":"Dividing the segment from 0 to 3/4 into equal parts of 1/4 and counting them"}],"after_explanation":"Fraction division 3/4 / 1/4 asks: how many 1/4-size pieces fit in 3/4 Answer: 3."},{"id":"2ece3a90-b00b-4b19-ae45-6fb61aab7571","lesson_number":"M6.NS.4.1","question_type":"multiple_choice","before_question_text":"Which situation is best represented by the number +$35 ","before_options":[{"key":"A","text":"Spending $35 at a store"},{"key":"B","text":"Owing $35 on a bill"},{"key":"C","text":"Earning $35 from babysitting"},{"key":"D","text":"Losing $35 from a wallet"}],"correct_answer":"C","before_explanation":"Positive values represent gains or increases; earning $35 is a gain.","after_question_text":"Which situation is best represented by the number +$35?","after_options":[{"key":"A","text":"Spending $35 at a store"},{"key":"B","text":"Owing $35 on a bill"},{"key":"C","text":"Earning $35 from babysitting"},{"key":"D","text":"Losing $35 from a wallet"}],"after_explanation":"Positive values represent gains or increases; earning $35 is a gain."},{"id":"a36b625c-f582-4582-aa52-fb1d52dd5a4b","lesson_number":"M6.NS.4.1","question_type":"multiple_choice","before_question_text":"A city's elevation is -48 feet. Which statement correctly interprets this value ","before_options":[{"key":"A","text":"The city is 48 feet above sea level"},{"key":"B","text":"The city is 48 feet below sea level"},{"key":"C","text":"The city is at sea level"},{"key":"D","text":"The city is 48 miles from the coast"}],"correct_answer":"B","before_explanation":"Negative elevation means below sea level; -48 feet means 48 feet below sea level.","after_question_text":"A city's elevation is -48 feet. Which statement correctly interprets this value?","after_options":[{"key":"A","text":"The city is 48 feet above sea level"},{"key":"B","text":"The city is 48 feet below sea level"},{"key":"C","text":"The city is at sea level"},{"key":"D","text":"The city is 48 miles from the coast"}],"after_explanation":"Negative elevation means below sea level; -48 feet means 48 feet below sea level."},{"id":"0e3f26e7-7c76-4546-8fb7-d1bb24e28292","lesson_number":"M6.NS.4.2","question_type":"multiple_choice","before_question_text":"What is the opposite of -15 ","before_options":[{"key":"A","text":"0"},{"key":"B","text":"15"},{"key":"C","text":"-(-15) which equals -15"},{"key":"D","text":"1/15"}],"correct_answer":"B","before_explanation":"The opposite of a number is its reflection over 0 on the number line. Opposite of -15 is +15.","after_question_text":"What is the opposite of -15?","after_options":[{"key":"A","text":"0"},{"key":"B","text":"15"},{"key":"C","text":"-(-15) which equals -15"},{"key":"D","text":"1/15"}],"after_explanation":"The opposite of a number is its reflection over 0 on the number line. Opposite of -15 is +15."},{"id":"40969ff7-0930-40e6-b31d-ca0687d47185","lesson_number":"M6.NS.4.2","question_type":"multiple_choice","before_question_text":"Which two numbers on a number line are both 7 units from zero ","before_options":[{"key":"A","text":"7 and 14"},{"key":"B","text":"7 and 0"},{"key":"C","text":"7 and -7"},{"key":"D","text":"0 and -7"}],"correct_answer":"C","before_explanation":"Opposites are equidistant from zero; both 7 and -7 are exactly 7 units from 0.","after_question_text":"Which two numbers on a number line are both 7 units from zero?","after_options":[{"key":"A","text":"7 and 14"},{"key":"B","text":"7 and 0"},{"key":"C","text":"7 and -7"},{"key":"D","text":"0 and -7"}],"after_explanation":"Opposites are equidistant from zero; both 7 and -7 are exactly 7 units from 0."},{"id":"1c68a49f-3f59-4caa-b2a3-93489e254060","lesson_number":"M6.RP.1.1","question_type":"multiple_choice","before_question_text":"A class has 12 boys and 16 girls. Which correctly expresses the ratio of boys to the total number of students ","before_options":[{"key":"A","text":"12:16"},{"key":"B","text":"16:12"},{"key":"C","text":"12:28"},{"key":"D","text":"28:12"}],"correct_answer":"C","before_explanation":"Ratio of boys to total = 12 : (12 + 16) = 12 : 28.","after_question_text":"A class has 12 boys and 16 girls. Which correctly expresses the ratio of boys to the total number of students?","after_options":[{"key":"A","text":"12:16"},{"key":"B","text":"16:12"},{"key":"C","text":"12:28"},{"key":"D","text":"28:12"}],"after_explanation":"Ratio of boys to total = 12 : (12 + 16) = 12 : 28."},{"id":"c25c4ff4-9035-4226-ba28-76ef19574b3d","lesson_number":"M6.RP.1.1","question_type":"multiple_choice","before_question_text":"Which of the following is NOT an equivalent way to write the ratio 3 to 5 ","before_options":[{"key":"A","text":"3:5"},{"key":"B","text":"3/5"},{"key":"C","text":"5/3"},{"key":"D","text":"3 to 5"}],"correct_answer":"C","before_explanation":"3 to 5, 3:5, and 3/5 are all equivalent. 5/3 reverses the relationship.","after_question_text":"Which of the following is NOT an equivalent way to write the ratio 3 to 5?","after_options":[{"key":"A","text":"3:5"},{"key":"B","text":"3/5"},{"key":"C","text":"5/3"},{"key":"D","text":"3 to 5"}],"after_explanation":"3 to 5, 3:5, and 3/5 are all equivalent. 5/3 reverses the relationship."},{"id":"5814a4c0-0b23-4518-96fe-de63212aca39","lesson_number":"M6.RP.1.2","question_type":"multiple_choice","before_question_text":"Which statement BEST defines a unit rate ","before_options":[{"key":"A","text":"A ratio that compares two quantities with the same units"},{"key":"B","text":"A rate with a denominator of 1"},{"key":"C","text":"Any fraction less than 1"},{"key":"D","text":"A rate that equals exactly 100"}],"correct_answer":"B","before_explanation":"A unit rate expresses the value per 1 unit of the second quantity (denominator = 1).","after_question_text":"Which statement BEST defines a unit rate?","after_options":[{"key":"A","text":"A ratio that compares two quantities with the same units"},{"key":"B","text":"A rate with a denominator of 1"},{"key":"C","text":"Any fraction less than 1"},{"key":"D","text":"A rate that equals exactly 100"}],"after_explanation":"A unit rate expresses the value per 1 unit of the second quantity (denominator = 1)."},{"id":"57124bd5-f00e-4c62-ac9f-971d292587d7","lesson_number":"M6.RP.3.1","question_type":"multiple_choice","before_question_text":"Which correctly expresses 45% as a rate per 100 ","before_options":[{"key":"A","text":"45/10"},{"key":"B","text":"45/1000"},{"key":"C","text":"45/100"},{"key":"D","text":"4.5/100"}],"correct_answer":"C","before_explanation":"Percent means 'per hundred,' so 45% = 45 per 100 = 45/100.","after_question_text":"Which correctly expresses 45% as a rate per 100?","after_options":[{"key":"A","text":"45/10"},{"key":"B","text":"45/1000"},{"key":"C","text":"45/100"},{"key":"D","text":"4.5/100"}],"after_explanation":"Percent means 'per hundred,' so 45% = 45 per 100 = 45/100."},{"id":"5c4f052d-b32e-45b2-8f98-8e242bef3449","lesson_number":"M6.RP.3.1","question_type":"multiple_choice","before_question_text":"A store says 3 out of every 100 items are returned. What percent of items are returned ","before_options":[{"key":"A","text":"0.03%"},{"key":"B","text":"3%"},{"key":"C","text":"30%"},{"key":"D","text":"300%"}],"correct_answer":"B","before_explanation":"3 out of 100 = 3/100 = 3%.","after_question_text":"A store says 3 out of every 100 items are returned. What percent of items are returned?","after_options":[{"key":"A","text":"0.03%"},{"key":"B","text":"3%"},{"key":"C","text":"30%"},{"key":"D","text":"300%"}],"after_explanation":"3 out of 100 = 3/100 = 3%."},{"id":"6387be34-849b-49b0-b391-e5ddee875bcb","lesson_number":"M6.SP.1.1","question_type":"multiple_choice","before_question_text":"Which of the following is a statistical question ","before_options":[{"key":"A","text":"How many students are in Ms. Taylor''s class today "},{"key":"B","text":"What is 8 x 7 "},{"key":"C","text":"How many minutes do 6th graders spend on homework each night "},{"key":"D","text":"What is the capital of North Carolina "}],"correct_answer":"C","before_explanation":"A statistical question anticipates variability across individuals -- different students will have different homework times.","after_question_text":"Which of the following is a statistical question?","after_options":[{"key":"A","text":"How many students are in Ms. Taylor''s class today"},{"key":"B","text":"What is 8 x 7"},{"key":"C","text":"How many minutes do 6th graders spend on homework each night"},{"key":"D","text":"What is the capital of North Carolina"}],"after_explanation":"A statistical question anticipates variability across individuals -- different students will have different homework times."},{"id":"81a06b69-e403-4f04-ba95-4bcd7bf2720b","lesson_number":"M6.SP.1.2","question_type":"multiple_choice","before_question_text":"A data set shows test scores: 72, 85, 90, 68, 91, 85, 77. What makes this a data SET rather than a single data point ","before_options":[{"key":"A","text":"The values are all different"},{"key":"B","text":"It contains multiple values from multiple observations"},{"key":"C","text":"All values are greater than 50"},{"key":"D","text":"The values are whole numbers"}],"correct_answer":"B","before_explanation":"A data set is a collection of values gathered from multiple observations or individuals.","after_question_text":"A data set shows test scores: 72, 85, 90, 68, 91, 85, 77. What makes this a data SET rather than a single data point?","after_options":[{"key":"A","text":"The values are all different"},{"key":"B","text":"It contains multiple values from multiple observations"},{"key":"C","text":"All values are greater than 50"},{"key":"D","text":"The values are whole numbers"}],"after_explanation":"A data set is a collection of values gathered from multiple observations or individuals."},{"id":"5a9025c6-eddb-4937-816f-7ea50e079529","lesson_number":"M6.SP.2.1","question_type":"multiple_choice","before_question_text":"Which type of display is BEST suited for showing the frequency of data grouped into intervals (e.g., ages 10-12, 13-15) ","before_options":[{"key":"A","text":"Dot plot"},{"key":"B","text":"Box plot"},{"key":"C","text":"Histogram"},{"key":"D","text":"Stem-and-leaf plot"}],"correct_answer":"C","before_explanation":"Histograms display data grouped into intervals (bins) with bar heights showing frequency.","after_question_text":"Which type of display is BEST suited for showing the frequency of data grouped into intervals (e.g., ages 10-12, 13-15)?","after_options":[{"key":"A","text":"Dot plot"},{"key":"B","text":"Box plot"},{"key":"C","text":"Histogram"},{"key":"D","text":"Stem-and-leaf plot"}],"after_explanation":"Histograms display data grouped into intervals (bins) with bar heights showing frequency."},{"id":"95a88626-1bcc-41b9-94eb-b7cf3e64668c","lesson_number":"M6.SP.4.1","question_type":"multiple_choice","before_question_text":"A histogram shows most data clustered on the right with a long tail to the left. This distribution is best described as:","before_options":[{"key":"A","text":"Symmetric"},{"key":"B","text":"Skewed right"},{"key":"C","text":"Skewed left"},{"key":"D","text":"Uniform"}],"correct_answer":"C","before_explanation":"Skewed left (negatively skewed) means most data is on the right with the tail extending to the left.","after_question_text":"A histogram shows most data clustered on the right with a long tail to the left. This distribution is best described as:","after_options":[{"key":"A","text":"Symmetric"},{"key":"B","text":"Skewed right"},{"key":"C","text":"Skewed left"},{"key":"D","text":"Uniform"}],"after_explanation":"Skewed left (negatively skewed) means most data is on the right with the tail extending to the left."},{"id":"e508b24a-6785-4e23-ab96-12b784a90a76","lesson_number":"M6.SP.4.2","question_type":"multiple_choice","before_question_text":"A data set has values: 12, 14, 15, 13, 11, 14, 87. What is likely the outlier and what measure of center does it most affect ","before_options":[{"key":"A","text":"87 is an outlier; it greatly affects the mean"},{"key":"B","text":"87 is an outlier; it greatly affects the median"},{"key":"C","text":"11 is an outlier; it affects the mode"},{"key":"D","text":"There is no outlier"}],"correct_answer":"A","before_explanation":"87 is far from the cluster 11-15; it is an outlier. Outliers have a large impact on the mean but minimal impact on the median.","after_question_text":"A data set has values: 12, 14, 15, 13, 11, 14, 87. What is likely the outlier and what measure of center does it most affect?","after_options":[{"key":"A","text":"87 is an outlier; it greatly affects the mean"},{"key":"B","text":"87 is an outlier; it greatly affects the median"},{"key":"C","text":"11 is an outlier; it affects the mode"},{"key":"D","text":"There is no outlier"}],"after_explanation":"87 is far from the cluster 11-15; it is an outlier. Outliers have a large impact on the mean but minimal impact on the median."},{"id":"04984eaa-b3dd-497e-b39d-6d0534fcfd04","lesson_number":"M6.SP.5.1","question_type":"multiple_choice","before_question_text":"A researcher collects the ages of 150 people at a community center. Which statement about this data set is appropriate ","before_options":[{"key":"A","text":"The data has 1 observation"},{"key":"B","text":"The data was collected in a context where age varies among individuals"},{"key":"C","text":"The data has no variability"},{"key":"D","text":"The data can only be displayed in a bar graph"}],"correct_answer":"B","before_explanation":"Summarizing a data set in context begins by noting that the data varies across the 150 individuals surveyed.","after_question_text":"A researcher collects the ages of 150 people at a community center. Which statement about this data set is appropriate?","after_options":[{"key":"A","text":"The data has 1 observation"},{"key":"B","text":"The data was collected in a context where age varies among individuals"},{"key":"C","text":"The data has no variability"},{"key":"D","text":"The data can only be displayed in a bar graph"}],"after_explanation":"Summarizing a data set in context begins by noting that the data varies across the 150 individuals surveyed."},{"id":"606c8082-2025-4982-a376-eed6d95c4cd2","lesson_number":"M6.SP.5.2","question_type":"multiple_choice","before_question_text":"A data set is symmetric and bell-shaped with no outliers. Which measure of center is MOST appropriate ","before_options":[{"key":"A","text":"Median only"},{"key":"B","text":"Mode only"},{"key":"C","text":"Mean (or median -- they are approximately equal)"},{"key":"D","text":"Range"}],"correct_answer":"C","before_explanation":"For symmetric distributions with no outliers, mean and median are approximately equal -- either is appropriate. The mean is often preferred.","after_question_text":"A data set is symmetric and bell-shaped with no outliers. Which measure of center is MOST appropriate?","after_options":[{"key":"A","text":"Median only"},{"key":"B","text":"Mode only"},{"key":"C","text":"Mean (or median -- they are approximately equal)"},{"key":"D","text":"Range"}],"after_explanation":"For symmetric distributions with no outliers, mean and median are approximately equal -- either is appropriate. The mean is often preferred."},{"id":"90b231df-485f-476c-aae3-188fe002fda3","lesson_number":"M6.SP.5.2","question_type":"multiple_choice","before_question_text":"A data set is heavily skewed right (with a few very large values). Which measure of center BEST represents the typical value ","before_options":[{"key":"A","text":"Mean"},{"key":"B","text":"Median"},{"key":"C","text":"Mode"},{"key":"D","text":"Range"}],"correct_answer":"B","before_explanation":"When data is skewed, the median is less affected by extreme values than the mean and better represents the typical observation.","after_question_text":"A data set is heavily skewed right (with a few very large values). Which measure of center BEST represents the typical value?","after_options":[{"key":"A","text":"Mean"},{"key":"B","text":"Median"},{"key":"C","text":"Mode"},{"key":"D","text":"Range"}],"after_explanation":"When data is skewed, the median is less affected by extreme values than the mean and better represents the typical observation."}]$g6_static_source$::jsonb;
  supplied_count integer;
  distinct_id_count integer;
  matching_count integer;
  updated_count integer;
  postcondition_count integer;
BEGIN
  SELECT COUNT(*), COUNT(DISTINCT e.id)
  INTO supplied_count, distinct_id_count
  FROM jsonb_to_recordset(source_rows) AS e(
    id uuid,
    lesson_number text,
    question_type text,
    before_question_text text,
    before_options jsonb,
    correct_answer text,
    before_explanation text,
    after_question_text text,
    after_options jsonb,
    after_explanation text
  );

  IF supplied_count <> expected_count OR distinct_id_count <> expected_count THEN
    RAISE EXCEPTION 'The embedded reviewed source set is invalid: expected % unique rows, found % rows and % unique IDs. No normalization applied.', expected_count, supplied_count, distinct_id_count;
  END IF;

  SELECT COUNT(*) INTO matching_count
  FROM public.static_questions AS sq
  JOIN jsonb_to_recordset(source_rows) AS e(
    id uuid,
    lesson_number text,
    question_type text,
    before_question_text text,
    before_options jsonb,
    correct_answer text,
    before_explanation text,
    after_question_text text,
    after_options jsonb,
    after_explanation text
  ) ON e.id = sq.id
  JOIN public.atomic_concepts AS ac ON ac.lesson_number = sq.concept_id
  JOIN public.unit_topics AS ut ON ut.id = ac.unit_topic_id
  JOIN public.courses AS c ON c.id = ut.course_id
  WHERE c.code = 'G6'
    AND sq.concept_id = e.lesson_number
    AND sq.question_type = e.question_type
    AND sq.question_text IS NOT DISTINCT FROM e.before_question_text
    AND sq.options IS NOT DISTINCT FROM e.before_options
    AND sq.correct_answer IS NOT DISTINCT FROM e.correct_answer
    AND sq.explanation IS NOT DISTINCT FROM e.before_explanation
    AND sq.is_active = TRUE
    AND COALESCE(sq.is_verified, FALSE) = FALSE;

  IF matching_count <> expected_count THEN
    RAISE EXCEPTION 'Live Grade 6 static source differs from the reviewed manifest: expected % exact candidate rows, found %. No normalization applied.', expected_count, matching_count;
  END IF;

  UPDATE public.static_questions AS sq
  SET
    question_text = e.after_question_text,
    options = e.after_options,
    explanation = e.after_explanation
  FROM jsonb_to_recordset(source_rows) AS e(
    id uuid,
    lesson_number text,
    question_type text,
    before_question_text text,
    before_options jsonb,
    correct_answer text,
    before_explanation text,
    after_question_text text,
    after_options jsonb,
    after_explanation text
  )
  WHERE sq.id = e.id;

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count <> expected_count THEN
    RAISE EXCEPTION 'Expected to normalize % rows but updated %. Transaction rolled back.', expected_count, updated_count;
  END IF;

  SELECT COUNT(*) INTO postcondition_count
  FROM public.static_questions AS sq
  JOIN jsonb_to_recordset(source_rows) AS e(
    id uuid,
    lesson_number text,
    question_type text,
    before_question_text text,
    before_options jsonb,
    correct_answer text,
    before_explanation text,
    after_question_text text,
    after_options jsonb,
    after_explanation text
  ) ON e.id = sq.id
  WHERE sq.concept_id = e.lesson_number
    AND sq.question_type = e.question_type
    AND sq.question_text IS NOT DISTINCT FROM e.after_question_text
    AND sq.options IS NOT DISTINCT FROM e.after_options
    AND sq.correct_answer IS NOT DISTINCT FROM e.correct_answer
    AND sq.explanation IS NOT DISTINCT FROM e.after_explanation
    AND sq.is_active = TRUE
    AND COALESCE(sq.is_verified, FALSE) = FALSE;

  IF postcondition_count <> expected_count THEN
    RAISE EXCEPTION 'Postcondition failed: expected % normalized rows with unchanged answer/activity/verification state, found %. Transaction rolled back.', expected_count, postcondition_count;
  END IF;
END $g6_static_normalization$;
